    pub const MEMORY_MODEL_RANGE: (usize, usize) = (2, 1);
    pub fn decode_memory_model_supplied(
        bytes: &[u8],
        offset: usize,
    ) -> Result<bool, openxcvr_core::supplied::SpanError> {
        let buf = openxcvr_core::supplied::field_bytes(bytes, offset, 2, 1)?;
        Ok((buf[0] >> 7) & 1 != 0)
    }

    pub const MODULE_STATE_RANGE: (usize, usize) = (3, 1);
    pub fn decode_module_state_supplied(
        bytes: &[u8],
        offset: usize,
    ) -> Result<CmisModuleState, openxcvr_core::supplied::SpanError> {
        let buf = openxcvr_core::supplied::field_bytes(bytes, offset, 3, 1)?;
        Ok(CmisModuleState::from((buf[0] >> 1) & 0x07 as u8))
    }

